-- 📚 꼭집 주거 사전 — 행복주택 형별 「우선 공급 계층 → 남은 물량 다른 계층으로」 · 행복주택 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 표준값 행복주택·행복주택(신혼희망). 갈래 무관 문장 정규식 + 맞은 행의 갈래 분포.
-- 정규식 둘: 기본(「우선 공급 … 남은·잔여 물량」 · 「남은 물량 … 다른 계층·공급 대상」) + 덧(같은 뜻을 「전환추첨」 · 「(계층·대상자) (순)으로 전환하여 공급」으로 쓰는 문장 — 「우선공급 미달 → 같은 대상자의 일반 공급물량으로 전환」은 같은 계층 안이라 뺀다). hits_base = 기본만 · hits = 둘 다 · added_ex = 덧으로만 잡힌 공고.
-- 확인 2026-10-29 · 실행 약 0.7초(2초 상한 · 관리 API 응답 시간 − 같은 시각 select 1 왕복) · 결과:
-- {"anns_all": 51, "hits_base": 10, "hits": 15, "by_std": {"행복주택": 15}, "by_cls": {"대상별 자격(청년·신혼·고령·주거약자 등)": 1, "모집 대상·공급 개요": 5, "선정 절차": 4, "순위": 1, "임대조건": 5}, "ex": ["21471_1_서울특별시_영등포구", "20648_1_경기도_광명시", "20647_1_경기도_광명시", "2015122300020960", "2015122300020958", "2015122300020925", "2015122300020919", "2015122300020917"], "added_ex": ["21471_1_서울특별시_영등포구", "2015122300020960", "2015122300020925", "2015122300020858", "2015122300020854"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.source src,x.title,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026 and a.std in('행복주택','행복주택(신혼희망)')),m0 as(select * from y where t~'우선\s*(으로\s*)?공급[^.]{0,160}(남은|잔여)\s*(물량|주택|세대|호)' or t~'(남은|잔여)\s*(물량|주택|세대)[^.]{0,60}(다른|추가|그\s*외|공급\s*대상)\s*(계층|공급)'),m as(select * from y where t~'우선\s*(으로\s*)?공급[^.]{0,160}(남은|잔여)\s*(물량|주택|세대|호)' or t~'(남은|잔여)\s*(물량|주택|세대)[^.]{0,60}(다른|추가|그\s*외|공급\s*대상)\s*(계층|공급)' or t~'전환\s*추첨' or t~'(자|계층)[”"’'']?\s*(순\s*)?(으로|로)\s*전환하여\s*(추첨\s*및\s*)?공급')select json_build_object('anns_all',(select count(distinct announcement_id) from y),'hits_base',(select count(distinct announcement_id) from m0),'hits',(select count(distinct announcement_id) from m),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from m group by 1)q),'by_cls',(select json_object_agg(coalesce(cls,'(갈래 없음)'),n) from(select cls,count(distinct announcement_id)n from m group by 1)q),'ex',(select json_agg(i) from(select distinct announcement_id i from m order by 1 desc limit 8)q),'added_ex',(select json_agg(i) from(select distinct announcement_id i from m where announcement_id not in(select announcement_id from m0) order by 1 desc)q))j;
